B.a0E=new A.am(B.cx,["Seviye 5","25 G\u0131da & Ta\u015f","0.25 Un / sn (2 G\u0131da -> 1 Un)","\xc7ay\u0131r Karosu"],t.w)
B.ZI=s(["Bu\u011fday Tarlas\u0131 ile F\u0131r\u0131n aras\u0131na k\xf6pr\xfc gibi yerle\u015ftirilmelidir."],t.s)
